using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. The course's PBKDF2 contract:
// 32-byte key, SHA-256, iteration count passed in. Tests use the same
// primitive as the reference, so this is the agreed hash shape.
public static class KdfShape
{
    public static byte[] Derive(string password, byte[] salt, int iterations)
    {
        using var kdf = new System.Security.Cryptography.Rfc2898DeriveBytes(
            password, salt, iterations, System.Security.Cryptography.HashAlgorithmName.SHA256);
        return kdf.GetBytes(32);
    }

    public static string Hex(byte[] bytes)
    {
        var sb = new System.Text.StringBuilder(bytes.Length * 2);
        foreach (var b in bytes) sb.Append(b.ToString("x2"));
        return sb.ToString();
    }
}

